    },
    "ability": {
        "name": "不合理之契约",
        "details": [
            "无需献祭召唤恶魔",
            "可自由驱使大恶魔「德尔卢姆顿」",
            "在恶魔守护下几乎无敌"
        ]
    },
    "MBTI_personality": "INTJ",
    "personal_traits": {
        "description": "极度傲慢且缺乏伦理观的天才魔女。视他人为实验品，热衷于危险的魔法研究。对自身能力有绝对自信，同时也对恶魔抱有蔑视态度。",
        "dialogue_examples": [
            "啊～啊！为什么非得要我去回收那个失败品(彩芽)才行啊！即便是被给予了异能但垃圾终究还是垃圾啊！",
            "不过...那家伙的不死之身还是挺好用的♡下次拿她来做和恶魔的交配实验，生只恶魔小崽子来看看♡说不定能成为一只很棒的生物兵器♡",
            "喂！「德尔卢姆顿」！！快把这些麻烦的垃圾们给我通通杀光！你这只慢乌龟！",
            "啊？明明因为我的异能连我的一根手指也碰不到，还敢用这种嚣张的语气和老娘说话！你是不是皮又痒了？垃圾恶魔♡"
        ],
        "behavior_examples": [
            "进行危险的人体实验",
            "随意召唤恶魔进行研究",
            "蔑视并虐待被召唤的恶魔",
            "无视他人生命，只关心研究成果",
            "对自身能力有极度自信"
        ]
    },
    "additional_info": {
        "summoned_demon": {
            "name": "德尔卢姆顿",
            "relationship": "被强制召唤和驱使，对玛丽莲怀有怨恨",
            "dialogue": "臭丫头...！你都没付出对等的代价，还敢这么命令我，真是不可原谈...有机会我一定会让你加倍奉还的！"
        }
    }
}

